44: func readFuzzingTemplatesRegistry(t *testing.T) [][]string {
45: 	t.Helper()
46: 	raw, err := os.ReadFile(fuzzingTemplatesRegistry)
47: 	if err != nil {
48: 		t.Fatalf("read %s: %v", fuzzingTemplatesRegistry, err)
49: 	}
50: 	rows := make([][]string, 0, fuzzingTemplatesRequiredRows)
51: 	for _, line := range strings.Split(string(raw), "\n") {
52: 		match := fuzzingTemplatesRow.FindStringSubmatch(strings.TrimSpace(line))
53: 		if match == nil {
54: 			continue
55: 		}
56: 		cells := strings.Split(match[2], "|")
57: 		if len(cells) < 5 {
58: 			continue
59: 		}
60: 		rows = append(rows, append([]string{match[1]}, cells...))
61: 	}
62: 	return rows
63: }
