190: // TestEveryCategoryIsAccountedFor — головна перевірка цього реєстру.
191: //
192: // Перелік категорій знімається з **оригіналу**, а не з того, що вже є в
193: // реєстрі: інакше здатність, яку ніхто не переносив, просто не потрапила б
194: // у перелік і виглядала б так, наче її немає.
195: //
196: // Тому: нова категорія в upstream зобов'язана з'явитися в реєстрі.
197: func TestEveryCategoryIsAccountedFor(t *testing.T) {
198: 	dir := fuzzingTemplatesDir(t)
199: 	entries, err := os.ReadDir(dir)
200: 	if err != nil {
201: 		t.Fatalf("read clone: %v", err)
202: 	}
203: 	total := 0
204: 	for _, entry := range entries {
205: 		if !entry.IsDir() {
206: 			continue
207: 		}
208: 		found, walkErr := filepath.Glob(filepath.Join(dir, entry.Name(), "*.yaml"))
209: 		if walkErr != nil {
210: 			t.Errorf("glob %s: %v", entry.Name(), walkErr)
211: 			continue
212: 		}
213: 		if len(found) == 0 {
214: 			continue
215: 		}
216: 		total += len(found)
217: 		registry, readErr := os.ReadFile(fuzzingTemplatesRegistry)
218: 		if readErr != nil {
219: 			t.Fatalf("read %s: %v", fuzzingTemplatesRegistry, readErr)
220: 		}
221: 		if !strings.Contains(string(registry), "`"+entry.Name()+"`") {
222: 			t.Errorf("the original has a %q category, and %s has no row "+
223: 				"naming it", entry.Name(), fuzzingTemplatesRegistry)
224: 		}
225: 	}
226: 	if total == 0 {
227: 		t.Fatalf("no templates found in %s: the registry's count cannot stand "+
228: 			"either way", dir)
229: 	}
230: 	registry, err := os.ReadFile(fuzzingTemplatesRegistry)
231: 	if err != nil {
232: 		t.Fatalf("read %s: %v", fuzzingTemplatesRegistry, err)
233: 	}
234: 	if !strings.Contains(string(registry), strconv.Itoa(total)) {
235: 		t.Errorf("the original holds %d templates, and the registry does not "+
236: 			"mention that number", total)
237: 	}
238: }
