32: // reconciliationVerdicts — вердикт-стан для рядка здатностей.
33: var reconciliationVerdicts = map[string]bool{
34: 	"супадає":       true,
35: 	"улучшено":      true,
36: 	"не перенесено": true,
37: }
38: 
39: // reconciliationRowRe ловить рядок таблиці здатностей: `| 7 | … |`.
40: // Число обов'язкове, бо без нього це будь-яка таблиця у файлі.
41: var reconciliationRowRe = regexp.MustCompile(`^\|\s*(\d+)\s*\|`)
42: 
43: // reconciliationVerdictRe дістає вердикт із рядка: перший із трьох, обгорнутий
44: // зворотними лапками. Пошук по рядку, а не по фіксованій колонці, бо різні
45: // реєстри мають різну кількість колонок, і колонка — деталь формату, а не
46: // зміст.
47: var reconciliationVerdictRe = regexp.MustCompile(
48: 	"`(" + "супадає|улучшено|не перенесено" + ")`")
49: 
50: // reconciliationSummaryRe ловить рядок підсумку виду:
51: //
52: //	| `не перенесено` | **4** |
53: //
54: // Назва вердикту в зворотних лапках, потім число в подвійному зірці.
55: var reconciliationSummaryRe = regexp.MustCompile(
56: 	`^\|\s*` + "`" + `([^` + "`" + `]+)` + "`" + `\s*\|\s*\*\*(\d+)\*\*\s*\|`)
57: 
58: // reconciliationCountRows рахує вердикти по рядках таблиці здатностей.
59: func reconciliationCountRows(t *testing.T, path string) (map[string]int, int) {
60: 	t.Helper()
61: 	raw, err := os.ReadFile(path)
62: 	if err != nil {
63: 		t.Fatalf("read %s: %v", path, err)
64: 	}
65: 	counts := map[string]int{}
66: 	total := 0
67: 	for _, line := range strings.Split(string(raw), "\n") {
68: 		if !reconciliationRowRe.MatchString(line) {
69: 			continue
70: 		}
71: 		match := reconciliationVerdictRe.FindStringSubmatch(line)
72: 		if match == nil || !reconciliationVerdicts[match[1]] {
73: 			continue
74: 		}
75: 		counts[match[1]]++
76: 		total++
77: 	}
78: 	return counts, total
79: }
80: 
81: // reconciliationSummary читає числа з рядків підсумку.
82: func reconciliationSummary(t *testing.T, path string) map[string]int {
83: 	t.Helper()
84: 	raw, err := os.ReadFile(path)
85: 	if err != nil {
86: 		t.Fatalf("read %s: %v", path, err)
87: 	}
88: 	summary := map[string]int{}
89: 	for _, line := range strings.Split(string(raw), "\n") {
90: 		match := reconciliationSummaryRe.FindStringSubmatch(line)
91: 		if match == nil || !reconciliationVerdicts[match[1]] {
92: 			continue
93: 		}
94: 		// Дубль у підсумку означає, що число в ньому не визначене.
95: 		if _, seen := summary[match[1]]; seen {
96: 			t.Errorf("%s states %q twice in its summary: the count is not a "+
97: 				"single claim, so neither occurrence can be checked", path, match[1])
98: 			continue
99: 		}
100: 		summary[match[1]], _ = strconv.Atoi(match[2])
101: 	}
102: 	return summary
103: }
104: 
105: // reconciliationRegistryFiles збирає всі реєстри звірки в дереві engine.
106: func reconciliationRegistryFiles(t *testing.T) []string {
107: 	t.Helper()
108: 	var found []string
109: 	for _, dir := range []string{".", "reconciliation"} {
110: 		entries, err := os.ReadDir(dir)
111: 		if err != nil {
112: 			// Каталогу може не бути — це не помилка, а відсутність даних.
113: 			continue
114: 		}
115: 		for _, entry := range entries {
116: 			if entry.IsDir() || !strings.HasSuffix(entry.Name(), "_reconciliation.md") {
117: 				continue
118: 			}
119: 			found = append(found, filepath.Join(dir, entry.Name()))
120: 		}
121: 	}
122: 	if len(found) == 0 {
123: 		t.Fatalf("no reconciliation registry found: this check would pass on an " +
124: 			"empty tree and prove nothing")
125: 	}
126: 	return found
127: }
