129: // TestEveryRegistrySummaryMatchesItsOwnRows — головна перевірка цього файлу.
130: //
131: // Кожен реєстр, який **заявляє** число вердиктів, звіряється з тим, що його
132: // рядки реально кажуть. Реєстр без заявленого числа пропускається: вимагати
133: // його тут означало б додавати вимогу, якої сам файл не встановлює.
134: func TestEveryRegistrySummaryMatchesItsOwnRows(t *testing.T) {
135: 	checked := 0
136: 	for _, path := range reconciliationRegistryFiles(t) {
137: 		summary := reconciliationSummary(t, path)
138: 		if len(summary) == 0 {
139: 			t.Logf("%s states no verdict counts in a summary: nothing to check", path)
140: 			continue
141: 		}
142: 		counts, total := reconciliationCountRows(t, path)
143: 		if total == 0 {
144: 			t.Errorf("%s states %d verdict counts but has no capability rows "+
145: 				"to check them against", path, len(summary))
146: 			continue
147: 		}
148: 		for verdict, claimed := range summary {
149: 			actual, ok := counts[verdict]
150: 			if !ok {
151: 				t.Errorf("%s claims %d rows of %q, and has none at all",
152: 					path, claimed, verdict)
153: 				continue
154: 			}
155: 			if claimed != actual {
156: 				t.Errorf("%s claims %d rows of %q in its summary, and its "+
157: 					"capability table holds %d", path, claimed, verdict, actual)
158: 			}
159: 		}
160: 		checked++
161: 	}
162: 	if checked == 0 {
163: 		t.Log("no registry states verdict counts yet: this check has not run " +
164: 			"against anything")
165: 	}
166: }
