package main

// Механічна перевірка реєстру звірки з `web-vulnerability`.
//
// Найменший репозиторій у всій партії: **один файл, 129 рядків**, і це не
// сканер, а навчальний приклад. Назва файлу читається інакше, тому реєстр
// мусить це сказати прямо — і перевірка стежить, щоб він не замовчав.
//
// Тому перевірка мірить саме «навчальність», а не архітектуру:
//
//  1. предмет звірки — коміт зафіксовано;
//  2. **наш код теж читається з `web/`**, бо `active_project_id` і
//     `export_bundle` живуть у Django, а не в Go;
//  3. головне — **що вважається доказом**. Оригінал доводить ін'єкцію
//     регуляркою `error|warning`, а ми читаємо справжню відповідь через
//     `enumDialects`. Різниця в цьому одному реченні тримає п'ять
//     `улучшено`;
//  4. два дефекти оригіналу, які треба назвати: сканування виконується
//     **на імпорті**, а функції `exploit_*` лише відкривають браузер.

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

const webvulnRegistry = "web_vulnerability_reconciliation.md"

const webvulnCommit = "d4a3893"

const webvulnRequiredRows = 9

// Оригінал — один файл, і його рядок 114 виконує запит на імпорті.
const webvulnOriginalLines = 129

var webvulnCloneRoots = []string{
	"../Semple-Интеграции/web-vulnerability",
	"../web-vulnerability",
}

var webvulnUpstreamCommit = regexp.MustCompile(
	`Upstream-коміт, звірка проти якого зроблена: ` + "`" + `([0-9a-f]{7,40})` + "`")

var webvulnVerdicts = map[string]bool{
	"супадає":       true,
	"улучшено":      true,
	"не перенесено": true,
}

var webvulnRow = regexp.MustCompile(`^\|\s*(\d+)\s*\|(.+)\|\s*$`)

func readWebvulnRegistry(t *testing.T) [][]string {
	t.Helper()
	raw, err := os.ReadFile(webvulnRegistry)
	if err != nil {
		t.Fatalf("read %s: %v", webvulnRegistry, err)
	}
	rows := make([][]string, 0, webvulnRequiredRows)
	for _, line := range strings.Split(string(raw), "\n") {
		match := webvulnRow.FindStringSubmatch(strings.TrimSpace(line))
		if match == nil {
			continue
		}
		cells := strings.Split(match[2], "|")
		if len(cells) < 5 {
			continue
		}
		rows = append(rows, append([]string{match[1]}, cells...))
	}
	return rows
}

func webvulnCell(row []string, index int) string {
	if index >= len(row) {
		return ""
	}
	return strings.Trim(strings.TrimSpace(row[index]), "`")
}

func webvulnDir(t *testing.T) string {
	t.Helper()
	for _, root := range webvulnCloneRoots {
		if info, err := os.Stat(root); err == nil && info.IsDir() {
			return root
		}
	}
	t.Skipf("web-vulnerability clone not found in %v: the registry's counts "+
		"cannot be verified against the original", webvulnCloneRoots)
	return ""
}

func webvulnOurTree(t *testing.T) string {
	t.Helper()
	parts := []string{}
	skip := func(name string) bool {
		return strings.HasSuffix(name, "_reconciliation_test.go") ||
			name == webvulnRegistry ||
			name == "reconciliation_summary_test.go"
	}
	for _, root := range []string{".", "pkg", "pkg/active", "pkg/scanner",
		"pkg/intruder", "pkg/enrich"} {
		entries, err := os.ReadDir(root)
		if err != nil {
			continue
		}
		for _, entry := range entries {
			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".go") ||
				skip(entry.Name()) {
				continue
			}
			raw, readErr := os.ReadFile(filepath.Join(root, entry.Name()))
			if readErr != nil {
				continue
			}
			parts = append(parts, string(raw))
		}
	}
	for _, dir := range []string{"../web/lab", "../web/core"} {
		entries, err := os.ReadDir(dir)
		if err != nil {
			continue
		}
		for _, entry := range entries {
			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".py") {
				continue
			}
			raw, readErr := os.ReadFile(filepath.Join(dir, entry.Name()))
			if readErr != nil {
				continue
			}
			parts = append(parts, string(raw))
		}
	}
	if len(parts) == 0 {
		t.Fatalf("no sources were read: the check would pass on an empty tree")
	}
	return strings.Join(parts, "\n")
}

// TestTheWebvulnRegistryFixesTheUpstreamCommit.
func TestTheWebvulnRegistryFixesTheUpstreamCommit(t *testing.T) {
	raw, err := os.ReadFile(webvulnRegistry)
	if err != nil {
		t.Fatalf("read %s: %v", webvulnRegistry, err)
	}
	match := webvulnUpstreamCommit.FindSubmatch(raw)
	if match == nil {
		t.Fatalf("%s does not record the upstream commit", webvulnRegistry)
	}
	if got := string(match[1]); got != webvulnCommit {
		t.Errorf("the registry pins commit %s, while this test expects %s: either "+
			"the clone moved and the registry needs a look, or the test is stale",
			got, webvulnCommit)
	}
}

// TestTheWebvulnRegistryHasEveryRowItPromises.
func TestTheWebvulnRegistryHasEveryRowItPromises(t *testing.T) {
	if got := len(readWebvulnRegistry(t)); got < webvulnRequiredRows {
		t.Errorf("%s has %d numbered rows, want at least %d",
			webvulnRegistry, got, webvulnRequiredRows)
	}
}

// TestEveryWebvulnRowHasAVerdictFromTheThree.
func TestEveryWebvulnRowHasAVerdictFromTheThree(t *testing.T) {
	for _, row := range readWebvulnRegistry(t) {
		verdict := webvulnCell(row, 3)
		if verdict == "" {
			t.Errorf("row %s has no verdict cell", row[0])
			continue
		}
		if !webvulnVerdicts[verdict] {
			t.Errorf("row %s verdict %q is not one of супадає / улучшено / не перенесено",
				row[0], verdict)
		}
	}
}

// TestEveryNotPortedWebvulnRowSaysWhy — причина обов'язкова.
func TestEveryNotPortedWebvulnRowSaysWhy(t *testing.T) {
	for _, row := range readWebvulnRegistry(t) {
		if webvulnCell(row, 3) != "не перенесено" {
			continue
		}
		tail := strings.Join(row[min(len(row), 5):], " | ")
		if strings.Trim(tail, " |") == "" {
			t.Errorf("row %s is не перенесено with no reason", row[0])
			continue
		}
		if !strings.Contains(strings.ToLower(tail), "причина") {
			t.Errorf("row %s is не перенесено but the reason never says why: %s", row[0], tail)
		}
	}
}

// TestEveryWebvulnRowNamesASymbolThatExists.
func TestEveryWebvulnRowNamesASymbolThatExists(t *testing.T) {
	tree := webvulnOurTree(t)
	for _, row := range readWebvulnRegistry(t) {
		symbol := webvulnCell(row, len(row)-1)
		if symbol == "" || symbol == "—" || symbol == "-" {
			continue
		}
		if !strings.Contains(tree, symbol) {
			t.Errorf("row %s claims symbol %q, which is not in our Go code or "+
				"in web/", row[0], symbol)
		}
	}
}

// TestTheOriginalStillCallsAServerErrorAProofOfInjection — рядок 1.
//
// Найважливіше твердження реєстру: їхній доказ ін'єкції — регулярка
// `error|warning` у відповіді. Це хибне: таке слово буває на здоровій цілі.
//
// Тому перевіряються обидві сторони: їхня перевірка і наша, бо `улучшено`
// тримається саме на тому, що наш доказ — справжня відповідь.
func TestTheOriginalStillCallsAServerErrorAProofOfInjection(t *testing.T) {
	dir := webvulnDir(t)
	raw, err := os.ReadFile(filepath.Join(dir, "web-vulnerability.py"))
	if err != nil {
		t.Fatalf("read web-vulnerability.py: %v", err)
	}
	text := string(raw)
	if !strings.Contains(text, `re.search(r"error|warning"`) {
		t.Error("the original no longer proves SQL injection with an " +
			"`error|warning` regex: row 1 records that as the difference " +
			"between their proof and ours, and it has changed")
	}

	tree := webvulnOurTree(t)
	if !strings.Contains(tree, "enumDialects") {
		t.Fatal("enumDialects is gone from our code: row 1 says we prove " +
			"injection with a real answer per dialect, and there is no " +
			"dialect left to ask")
	}
	if !strings.Contains(tree, "enumAsk") {
		t.Error("enumAsk is gone: it is what turns a dialect into a real " +
			"read of the schema, and without it the union is only a guess")
	}
}

// TestWeCarryFourDialectsAndThreeXSSModules.
//
// Числа реєстру тримають два рядки (`улучшено` на SQLi і на XSS), тому вони
// вимірюються, а не беруться з тексту.
func TestWeCarryFourDialectsAndThreeXSSModules(t *testing.T) {
	raw, err := os.ReadFile("pkg/active/enumerate.go")
	if err != nil {
		t.Fatalf("read enumerate.go: %v", err)
	}
	dialects := strings.Count(string(raw), "name:      \"")
	if dialects < 4 {
		t.Errorf("our enumDialects list holds %d dialects, the registry claims "+
			"at least 4", dialects)
	}

	raw, err = os.ReadFile("pkg/active/detect_xss.go")
	if err != nil {
		t.Fatalf("read detect_xss.go: %v", err)
	}
	if !strings.Contains(string(raw), `return "xss"`) {
		t.Error("the plain xss module is gone: the registry counts three XSS " +
			"modules, and one of them no longer exists")
	}

	raw, err = os.ReadFile("pkg/active/detect_xss_escape.go")
	if err != nil {
		t.Fatalf("read detect_xss_escape.go: %v", err)
	}
	if !strings.Contains(string(raw), `return "xss-escape"`) {
		t.Error("the xss-escape module is gone: row 2 says we separate a broken " +
			"escape from a working one with a gap, and that separation is gone")
	}
}

// TestTheOriginalScansExampleDotComOnImport — рядок 6.
//
// Дефект оригіналу, який треба назвати: запит виконується **на імпорті**.
// Відкрив файл — і вже зробив запит до example.com. У нас такого немає:
// рушій чекає на оператора.
func TestTheOriginalScansExampleDotComOnImport(t *testing.T) {
	dir := webvulnDir(t)
	raw, err := os.ReadFile(filepath.Join(dir, "web-vulnerability.py"))
	if err != nil {
		t.Fatalf("read web-vulnerability.py: %v", err)
	}
	text := string(raw)

	atModuleLevel := strings.Contains(text, "scan_website(\"https://www.example.com\")")
	if !atModuleLevel {
		t.Error("the original no longer calls scan_website at module level: " +
			"row 6 records the scan-on-import defect, and it may be fixed")
	}

	// Наша сторона: жоден Go-файл движка не робить цілевий запит на
	// верхньому рівні. Перевіряється тим, що імена їхньої функції
	// `scan_website` у нашому коді немає.
	if strings.Contains(webvulnOurTree(t), "scan_website") {
		t.Error("our code now contains scan_website: row 6 says nothing in " +
			"our engine scans on load, and that boundary no longer holds")
	}
}

// TestTheSoCalledExploitsOnlyOpenABrowser — рядок 5.
//
// `exploit_sql_injection` і `exploit_xss_vulnerability` не експлуатують
// нічого: обидві викликають `webbrowser.open(url)`. Реєстр зобов'язаний
// назвати це, бо назва функції каже протилежне.
func TestTheSoCalledExploitsOnlyOpenABrowser(t *testing.T) {
	dir := webvulnDir(t)
	raw, err := os.ReadFile(filepath.Join(dir, "web-vulnerability.py"))
	if err != nil {
		t.Fatalf("read web-vulnerability.py: %v", err)
	}
	text := string(raw)

	for _, fn := range []string{"exploit_sql_injection", "exploit_xss_vulnerability"} {
		start := strings.Index(text, "def "+fn+"(")
		if start < 0 {
			t.Errorf("the original no longer defines %s: row 5 names it as a "+
				"function that does not exploit anything", fn)
			continue
		}
		end := strings.Index(text[start:], "\ndef ")
		body := text[start:]
		if end > 0 {
			body = text[start : start+end]
		}
		if !strings.Contains(body, "webbrowser.open") {
			t.Errorf("%s no longer opens a browser: row 5 says these "+
				"functions are named exploit but only display the page, and "+
				"that is no longer what they do", fn)
		}
	}
}

// TestTheOriginalChecksReflectionAndASchemaPrefix.
//
// Два докази оригіналу, які реєстр наводить дослівно: XSS — це дослівне
// відбиття пейлоада, «небезпечна конфігурація» — це URL без `https`.
func TestTheOriginalChecksReflectionAndASchemaPrefix(t *testing.T) {
	dir := webvulnDir(t)
	raw, err := os.ReadFile(filepath.Join(dir, "web-vulnerability.py"))
	if err != nil {
		t.Fatalf("read web-vulnerability.py: %v", err)
	}
	text := string(raw)

	if !strings.Contains(text, "<script>alert('XSS')</script>") ||
		!strings.Contains(text, "payload in response.text") {
		t.Error("the original no longer proves XSS by verbatim reflection: " +
			"row 2 quotes that proof as the thing our three modules beat")
	}
	if !strings.Contains(text, `url.startswith("https")`) {
		t.Error("the original no longer treats a non-https URL as an insecure " +
			"configuration: row 3 describes that check as the whole of its " +
			"configuration coverage")
	}
}

// TestTheOriginalIsStillOneShortFile.
//
// Число 129 рядків тримає читабельність висновку реєстру: «замало, щоб
// робити висновок про якість». Якщо оригінал розростеться, висновок треба
// перечитати.
func TestTheOriginalIsStillOneShortFile(t *testing.T) {
	dir := webvulnDir(t)
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatalf("read %s: %v", dir, err)
	}
	sources := 0
	total := 0
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".py") {
			continue
		}
		raw, readErr := os.ReadFile(filepath.Join(dir, entry.Name()))
		if readErr != nil {
			continue
		}
		sources++
		total += strings.Count(string(raw), "\n")
	}
	if sources != 1 {
		t.Errorf("the original has %d python files, the registry describes a "+
			"single 129-line file", sources)
	}
	if total > webvulnOriginalLines*2 {
		t.Errorf("the original grew to %d lines (was %d): the registry calls "+
			"it a teaching example, and a tool that size deserves a real "+
			"review", total, webvulnOriginalLines)
	}
}

// TestTheRegistryCallsItATeachingExample.
//
// Назва файлу `web-vulnerability.py` читається інакше, ніж зміст: 129 рядків
// із двома пейлоадами й `webbrowser.open` — це приклад, а не інструмент.
// Реєстр мусить це сказати, інакше п'ять `улучшено` прочитаються як
// приниження замість порівняння.
func TestTheRegistryCallsItATeachingExample(t *testing.T) {
	raw, err := os.ReadFile(webvulnRegistry)
	if err != nil {
		t.Fatalf("read %s: %v", webvulnRegistry, err)
	}
	text := strings.ToLower(string(raw))
	if !strings.Contains(text, "навчальний") {
		t.Error("the registry never calls it a teaching example: without that " +
			"sentence the filename reads as a scanner, and the whole " +
			"comparison changes meaning")
	}
}

