package main

// Механічна перевірка того, що **кожен реєстр фіксує upstream-коміт**.
//
// Цей тест написаний після власної помилки. При синхронізації документів у
// `Прочее/` я виміряла «скільки реєстрів фіксують коміт» скриптом, який шукав
// **один** рядок — `Upstream-коміт, звірка проти якого зроблена:` — і отримала
// «30 з 38». Я записала це в документи як відкритий пункт.
//
// Вимірювання показало: **коміт фіксують усі 38**. Вісім «невідповідних»
// реєстрів просто роблять це іншим форматом —
//
//	новий формат: Upstream-коміт, звірка проти якого зроблена: `1e67fe9`
//	старий:      Коміт оригіналу: `5e46a45…`
//	таблиця:     | Arachni | …/arachni | `9cd73f25…` | 2026-04-22 |
//
// Тобто цебула той самий випадок, який `AGENTS.md` описує як «3 = 3»:
// правильне число не застосували, і воно мовчало.
//
// Тепер правило механічне: реєстр **зобов'язаний** містити хоч б один
// upstream-коміт у backticks **і** слово про коміт поруч. Формат значення не
// має значення — має значення факт.

import (
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"
)

// Канонічний заголовок нових реєстрів.
var canonicalCommitHeader = regexp.MustCompile(
	`Upstream-коміт, звірка проти якого зроблена: ` + "`" + `([0-9a-f]{7,40})` + "`")

// Будь-який 7–40-символьний hex-рядок у backticks.
var anyCommit = regexp.MustCompile("`([0-9a-f]{7,40})`")

// Слово про коміт — щоб `deadbeef` у прикладі не вважався доказом.
var commitContext = regexp.MustCompile(`(?i)коміт|комит|commit`)

// Опис формату, у якому реєстр фіксує коміт.
func upstreamCommitOf(text string) (commit string, format string) {
	if m := canonicalCommitHeader.FindStringSubmatch(text); m != nil {
		return m[1], "canonical"
	}
	if m := regexp.MustCompile(`(?i)[Кк]оміт[^\n|]*:?[^|\n]*` + "`([0-9a-f]{7,40})`").
		FindStringSubmatch(text); m != nil {
		return m[1], "коміт оригіналу"
	}
	if m := regexp.MustCompile(`(?i)коміт[^\n]*upstream[^\n]*\n[^\n]*` + "`([0-9a-f]{7,40})`").
		FindStringSubmatch(text); m != nil {
		return m[1], "таблиця комітів"
	}
	// Останній варіант: у файлі є і слово про коміт, і hex у backticks.
	if commitContext.MatchString(text) {
		for _, m := range anyCommit.FindAllStringSubmatch(text, -1) {
			// відкидаємо те, що схоже на звичайний код (літери a-f є),
			// і залишаємо те, що стоїть у рядку про коміт
			if strings.Contains(strings.ToLower(m[1]), "deadbeef") {
				continue
			}
			return m[1], "змішаний"
		}
	}
	return "", ""
}

func reconciliationRegistryFiles(t *testing.T) []string {
	t.Helper()
	files := []string{}
	add := func(pattern string) {
		matches, err := filepath.Glob(pattern)
		if err != nil {
			return
		}
		for _, m := range matches {
			if strings.HasSuffix(m, "_reconciliation.md") {
				files = append(files, m)
			}
		}
	}
	// `filepath.Glob` не підтримує `**`, тому підпакиети обходимо вручну.
	add("*_reconciliation.md")
	for _, root := range []string{"pkg", "pkg/active", "pkg/scanner",
		"pkg/intruder", "pkg/enrich", "pkg/bypass", "pkg/passive"} {
		entries, err := os.ReadDir(root)
		if err != nil {
			continue
		}
		for _, entry := range entries {
			if entry.IsDir() || !strings.HasSuffix(entry.Name(), "_reconciliation.md") {
				continue
			}
			files = append(files, filepath.Join(root, entry.Name()))
		}
	}
	sort.Strings(files)
	return files
}

// TestEveryReconciliationRegistryFixesItsUpstreamCommit — головне твердження.
//
// Падає, якщо реєстр **не** називає upstream-коміт. Саме цього тесту не
// було, і через це моя хибна цифра «30 з 38» трималася в документах годину.
func TestEveryReconciliationRegistryFixesItsUpstreamCommit(t *testing.T) {
	files := reconciliationRegistryFiles(t)
	if len(files) < 30 {
		t.Fatalf("found only %d registries, expected the project to have at "+
			"least 30: the walk is broken, and a walk that sees nothing "+
			"reports success", len(files))
	}

	missing := []string{}
	formats := map[string]int{}
	for _, f := range files {
		raw, err := os.ReadFile(f)
		if err != nil {
			t.Fatalf("read %s: %v", f, err)
		}
		commit, format := upstreamCommitOf(string(raw))
		if commit == "" {
			missing = append(missing, f)
			continue
		}
		formats[format]++
	}

	if len(missing) > 0 {
		t.Errorf("%d of %d registries name no upstream commit, and a table "+
			"against an unpinned commit is a table about a different subject: "+
			"%v", len(missing), len(files), missing)
	}
	t.Logf("%d registries checked, formats: %v", len(files), formats)
}

// TestTheCommitIsAShaNotAnAccident.
//
// Коміт має бути **SHA**, а не випадковий рядок шістнадцяткового вигляду.
// Перевіряється довжина і те, що поряд стоїть слово про коміт.
func TestTheCommitIsAShaNotAnAccident(t *testing.T) {
	for _, f := range reconciliationRegistryFiles(t) {
		raw, err := os.ReadFile(f)
		if err != nil {
			t.Fatalf("read %s: %v", f, err)
		}
		text := string(raw)
		commit, _ := upstreamCommitOf(text)
		if commit == "" {
			continue
		}
		if len(commit) < 7 {
			t.Errorf("%s names commit %q, which is too short to be a SHA",
				f, commit)
		}
		if !commitContext.MatchString(text) {
			t.Errorf("%s names commit %q but never says what it is: a hex "+
				"string without the word 'коміт' next to it is not a pin", f, commit)
		}
		for _, r := range commit {
			if !strings.ContainsRune("0123456789abcdef", r) {
				t.Errorf("%s names commit %q, which is not hexadecimal", f, commit)
				break
			}
		}
	}
}

